#!/usr/bin/env bash
# =============================================================================
# storage-mounts.sh — set up passwordless SSH to the remote storage boxes and
# mount the primary box's gmail + databases shares into the admin user's home.
#
#   sudo bash scripts/storage-mounts.sh
#
# What it does:
#   1. Uses the server's standard SSH key (~/.ssh/id_ed25519, generated by
#      host-setup.sh) — the same key used for the snapshot sync and backups.
#   2. Installs its public half on ALL THREE boxes (primary, secondary and the
#      backup box), so connecting never asks for a password. Asks for each
#      box's password ONCE. Existing keys are PRESERVED — Hetzner's
#      `install-ssh-key` appends, it never replaces.
#   3. Writes /etc/fstab entries for the primary box's mounts only (_netdev,
#      x-systemd.automount, reconnect), then mounts them now. The secondary
#      box and the backup box are authorised but NOT mounted.
#
# Config (override in .env, all optional; legacy HETZNER_* names also accepted):
#   STORAGE_PRIMARY_HOST    default u458814.your-storagebox.de
#   STORAGE_PRIMARY_USER    default u458814
#   STORAGE_SECONDARY_HOST  default u513410.your-storagebox.de
#   STORAGE_SECONDARY_USER  default u513410
#   BACKUP_HOST             default u676107.your-storagebox.de (backup box)
#   BACKUP_USER             default u676107
#   STORAGE_PORT            default 23 (all three boxes)
#   STORAGE_MOUNT_HOME      default: home of the invoking user (~)
#   STORAGE_MOUNT_USER      default: $SUDO_USER, else ryan, else current user
#   STORAGE_KEY             default: $STORAGE_MOUNT_HOME/.ssh/id_ed25519
# =============================================================================
set -euo pipefail
SELF="$(readlink -f "$0")"
cd "$(dirname "$SELF")/.."

# ---- root is needed to write /etc/fstab and mount sshfs system-wide ----
if [ "$(id -u)" -ne 0 ]; then
  exec sudo -E bash "$SELF" "$@"
fi

[ -f .env ] && set -a && source .env && set +a

say()  { printf '\033[1;36m==>\033[0m %s\n' "$*"; }
ok()   { printf '\033[1;32m[ok]\033[0m %s\n' "$*"; }
warn() { printf '\033[1;33m[!!]\033[0m %s\n' "$*"; }

PORT="${STORAGE_PORT:-${HETZNER_SSH_PORT:-23}}"

PRIMARY_HOST="${STORAGE_PRIMARY_HOST:-${HETZNER_PRESSABL_HOST:-u458814.your-storagebox.de}}"
PRIMARY_USER="${STORAGE_PRIMARY_USER:-${HETZNER_PRESSABL_USER:-u458814}}"
SECONDARY_HOST="${STORAGE_SECONDARY_HOST:-${HETZNER_SECONDARY_HOST:-u513410.your-storagebox.de}}"
SECONDARY_USER="${STORAGE_SECONDARY_USER:-${HETZNER_SECONDARY_USER:-u513410}}"
# The off-site backup box (the new server WRITES here; it is never mounted).
BACKUP_HOST="${BACKUP_HOST:-u676107.your-storagebox.de}"
BACKUP_USER="${BACKUP_USER:-u676107}"

# All three boxes get the key; only the primary box gets mounts.
BOXES=("$PRIMARY_USER@$PRIMARY_HOST" "$SECONDARY_USER@$SECONDARY_HOST" \
       "$BACKUP_USER@$BACKUP_HOST")
# mount spec: "user@host:remote-dir  local-folder-name"
# The box's /home/databases is mounted at ~/mariadbs (the canonical local name
# used by DB_DUMP_DIR / backup.sh); ~/databases no longer exists.
MOUNT_SPECS=("$PRIMARY_USER@$PRIMARY_HOST:/home/gmail gmail" \
             "$PRIMARY_USER@$PRIMARY_HOST:/home/databases mariadbs")

# ---- where to mount: the invoking user's home (~) ----
resolve_mount_user() {
  if [ -n "${STORAGE_MOUNT_USER:-${HETZNER_MOUNT_USER:-}}" ]; then
    printf '%s' "${STORAGE_MOUNT_USER:-$HETZNER_MOUNT_USER}"; return
  fi
  if [ -n "${SUDO_USER:-}" ] && [ "$SUDO_USER" != "root" ]; then printf '%s' "$SUDO_USER"; return; fi
  if id ryan >/dev/null 2>&1; then printf '%s' "ryan"; return; fi
  id -un
}
MOUNT_USER="$(resolve_mount_user)"
MOUNT_HOME="${STORAGE_MOUNT_HOME:-${HETZNER_MOUNT_HOME:-$(getent passwd "$MOUNT_USER" | cut -d: -f6)}}"
[ -n "$MOUNT_HOME" ] || { warn "Could not resolve a home directory for '$MOUNT_USER'."; exit 1; }
MOUNT_UID="$(id -u "$MOUNT_USER")"
MOUNT_GID="$(id -g "$MOUNT_USER")"
KEY="${STORAGE_KEY:-${HETZNER_IDENTITY_FILE:-$MOUNT_HOME/.ssh/id_ed25519}}"

# ---- packages ----
if ! command -v sshfs >/dev/null 2>&1; then
  say "Installing sshfs"
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y sshfs
fi

# FUSE only honours `allow_other` when it is enabled in /etc/fuse.conf.
if [ -f /etc/fuse.conf ] && ! grep -qs '^[[:space:]]*user_allow_other' /etc/fuse.conf; then
  printf '\nuser_allow_other\n' >> /etc/fuse.conf
fi

# ---- keypair ----
SSH_DIR="$(dirname "$KEY")"
install -d -m 700 "$SSH_DIR"
chown "$MOUNT_UID:$MOUNT_GID" "$SSH_DIR" 2>/dev/null || true
if [ ! -f "$KEY" ]; then
  say "Generating storage SSH key: $KEY"
  ssh-keygen -t ed25519 -N '' -C "server-setup storage" -f "$KEY" >/dev/null
  chmod 600 "$KEY"
  chmod 644 "$KEY.pub"
  chown "$MOUNT_UID:$MOUNT_GID" "$KEY" "$KEY.pub" 2>/dev/null || true
fi

key_works() { # "$1" user@host
  ssh -i "$KEY" -p "$PORT" -o BatchMode=yes -o IdentitiesOnly=yes \
      -o PreferredAuthentications=publickey -o StrictHostKeyChecking=accept-new \
      "$1" ls >/dev/null 2>&1
}

install_key() { # "$1" user@host
  local target="$1"
  if key_works "$target"; then
    ok "Passwordless SSH to $target already works."
    return 0
  fi
  if [ ! -e /dev/tty ]; then
    warn "A terminal is needed to enter the Storage Box password exactly once."
    warn "Re-run from an interactive shell: sudo bash scripts/storage-mounts.sh"
    return 1
  fi
  say "Installing this server's public key on $target"
  say "You will be asked for that box's password ONCE. Existing keys are kept."
  if cat "$KEY.pub" | ssh -p "$PORT" -o StrictHostKeyChecking=accept-new \
       "$target" install-ssh-key; then
    :
  elif command -v ssh-copy-id >/dev/null 2>&1 \
       && ssh-copy-id -p "$PORT" -s -i "$KEY.pub" "$target"; then
    :
  else
    warn "Automatic key install failed for $target."
    warn "Add this public key to that box's /home/.ssh/authorized_keys (OpenSSH"
    warn "format) by hand, then re-run:"
    printf '\n    %s\n\n' "$(cat "$KEY.pub")"
    return 1
  fi
  if key_works "$target"; then
    ok "Passwordless SSH to $target is working."
    return 0
  fi
  warn "The key was installed on $target but passwordless login still fails."
  warn "Check that SSH support is enabled for that Storage Box in the Hetzner Console."
  return 1
}

# ---- 1. passwordless auth on ALL THREE boxes (primary, secondary, backup) ----
for target in "${BOXES[@]}"; do
  install_key "$target" || exit 1
done

# ---- 2. /etc/fstab: persistent automounts for the primary box (idempotent) ----
FSTAB=/etc/fstab
BEGIN='# BEGIN server-setup storage mounts'
END='# END server-setup storage mounts'
[ -f "$FSTAB.server-setup.bak" ] || cp "$FSTAB" "$FSTAB.server-setup.bak"

OPTS="_netdev,nofail,x-systemd.automount,x-systemd.idle-timeout=60,IdentityFile=$KEY,port=$PORT,uid=$MOUNT_UID,gid=$MOUNT_GID,allow_other,reconnect,ServerAliveInterval=15,ServerAliveCountMax=3,StrictHostKeyChecking=accept-new"

TMP="$(mktemp)"
if grep -qsF "$BEGIN" "$FSTAB"; then
  awk -v b="$BEGIN" -v e="$END" '$0==b{skip=1} !skip{print} $0==e{skip=0}' "$FSTAB" > "$TMP"
else
  cp "$FSTAB" "$TMP"
fi
{
  printf '%s\n' "$BEGIN"
  for spec in "${MOUNT_SPECS[@]}"; do
    printf '%s %s/%s fuse.sshfs %s 0 0\n' "${spec%% *}" "$MOUNT_HOME" "${spec##* }" "$OPTS"
  done
  printf '%s\n' "$END"
} >> "$TMP"
cat "$TMP" > "$FSTAB"
rm -f "$TMP"
say "Updated $FSTAB (backup: $FSTAB.server-setup.bak)"

if command -v systemctl >/dev/null 2>&1; then
  systemctl daemon-reload
fi

# ---- 2b. retire the old ~/databases mount (renamed to ~/mariadbs) -----------
# Older installs mounted the box's /home/databases at ~/databases. The canonical
# name is now ~/mariadbs; unmount and remove the stale mountpoint so no empty,
# confusing directory lingers.
STALE_DB_DIR="$MOUNT_HOME/databases"
if mountpoint -q "$STALE_DB_DIR" 2>/dev/null; then
  say "Unmounting retired ~/databases (now ~/mariadbs)"
  umount "$STALE_DB_DIR" 2>/dev/null || umount -l "$STALE_DB_DIR" 2>/dev/null || warn "Could not unmount $STALE_DB_DIR"
fi
if [ -d "$STALE_DB_DIR" ]; then
  rmdir "$STALE_DB_DIR" 2>/dev/null && say "Removed retired $STALE_DB_DIR" \
    || warn "$STALE_DB_DIR still exists (not empty?) — remove it by hand if stale."
fi

# ---- 3. mount now ----
for spec in "${MOUNT_SPECS[@]}"; do
  connection="${spec%% *}"   # user@host:/remote/dir
  name="${spec##* }"         # local folder name
  local_dir="$MOUNT_HOME/$name"

  if mountpoint -q "$local_dir" 2>/dev/null; then
    ok "Already mounted: $local_dir"
    continue
  fi

  mkdir -p "$local_dir"
  chown "$MOUNT_UID:$MOUNT_GID" "$local_dir" 2>/dev/null || true

  say "Mounting $connection -> $local_dir"
  mounted=0
  if command -v systemctl >/dev/null 2>&1; then
    # Start the automount unit and touch the path to trigger the actual mount.
    systemctl restart "$(systemd-escape -p --suffix=automount "$local_dir")" >/dev/null 2>&1 || true
    ls "$local_dir" >/dev/null 2>&1 || true
    mountpoint -q "$local_dir" && mounted=1
  fi
  if [ "$mounted" -eq 0 ]; then
    if sshfs "$connection" "$local_dir" -p "$PORT" \
        -o "IdentityFile=$KEY,uid=$MOUNT_UID,gid=$MOUNT_GID,allow_other,reconnect,ServerAliveInterval=15,ServerAliveCountMax=3,StrictHostKeyChecking=accept-new"; then
      mounted=1
    fi
  fi

  if [ "$mounted" -eq 1 ]; then
    ok "Mounted $local_dir"
  else
    warn "Could not mount $local_dir."
    warn "Check the Storage Box is reachable, then re-run: sudo bash scripts/storage-mounts.sh"
  fi
done

echo
echo "Done. Passwordless access to all three boxes; u458814 gmail+mariadbs mounted under $MOUNT_HOME."
echo "Mounts are in /etc/fstab and reappear automatically after reboot."
